import java.io.*;

public class Main {
    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        int m = fs.nextInt();
        int current = fs.nextInt();

        int[] nextSong = new int[m + 1];

        for (int i = 0; i < n; i++) {
            int adored = fs.nextInt();
            int hated = fs.nextInt();
            if (nextSong[hated] == 0) {
                nextSong[hated] = adored;
            }
        }

        boolean[] visited = new boolean[m + 1];
        int swaps = 0;

        while (true) {
            if (nextSong[current] == 0) {
                System.out.println(swaps);
                return;
            }
            if (visited[current]) {
                System.out.println(-1);
                return;
            }

            visited[current] = true;
            current = nextSong[current];
            swaps++;
        }
    }
}
